void Reset() {
  //чистим еепром для ресета в заводские настройки
  for (int i = 0 ; i < EEPROM.length() ; i++) {
    EEPROM.write(i, 0);
  }
}

void BurnerInit()
{
  //При включении инициализируется дисплей и датчики температуры
  //и выводятся на дисплей текущая температура масла и воды.

  //SERIAL PORT INIT
  Serial.begin(9600);

  //назначение вход-выход
  //output interfaces (switches)
  pinMode(AirValve, OUTPUT);
  pinMode(FanSwitch, OUTPUT);
  pinMode(HeaterSwitch, OUTPUT);
  pinMode(IgnitionSwitch, OUTPUT);
  pinMode(FuelPumpSwitch, OUTPUT);

  //input interfaces (sensors):
  pinMode(EncoderButton, INPUT_PULLUP);
  pinMode(FuelLevelSensor, INPUT);//включаем подтягивающий резистор к плюсу для фотодатчика.
  pinMode(OpticalSensor, INPUT);//включаем подтягивающий резистор к плюсу для кнопки.

  pinMode(ThermostatButton, INPUT);
  pinMode(PowerInput, INPUT);

  digitalWrite(FuelLevelSensor, HIGH);
  digitalWrite(ThermostatButton, HIGH);
  //цепляемся раздребезгом к кнопке
  DebouncedEncoder.attach(EncoderButton);
  DebouncedEncoder.interval(50);

  //для начала все релюхи в положение ВЫКЛЮЧЕНО
  digitalWrite(FanSwitch, LOW);
  digitalWrite (AirValve, LOW);
  digitalWrite (HeaterSwitch, LOW);
  digitalWrite (FuelPumpSwitch, LOW);


  //включить дисплей и подсветку дисплея
  lcd.init();
  lcd.backlight ();

  //Берем данные из ПЗУ если они там есть
  int EPrW = EEPROM.read(WaterEepromAddress);
  if (EPrW >= MinimumWaterTemp && EPrW <= MaximumWaterTemp ) {
    DesiredWaterTemp = EPrW;
  }

  int EPrWG = EEPROM.read(WaterGisteresisEepromAddress);
  if (EPrWG >= MinimumWaterGisteresisTemp && EPrWG <= MaximumWaterGisteresisTemp ) {
    DesiredWaterGisteresisTemp = EPrWG;
  }

  int EPrO = EEPROM.read(FuelEepromAddress);
  if (EPrO >= MinimumFuelTemp && EPrO <= MaximumFuelTemp ) {
    DesiredFuelTemp = EPrO;
  }

  int EPrOPER = EEPROM.read(OperationEepromAddress);
  if (EPrOPER >= 0 && EPrOPER <= 1 ) {
    OperationMode = EPrOPER;
  }
//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
  int EPrSf = EEPROM.read(FanSwitchPWMEepromAddress);
  if (EPrSf >= MinimumFanSwitchPWM && EPrSf <= MaximumFanSwitchPWM ) {
    FanSwitchPWM = EPrSf;
  }

  // Время первой проверки ТЭНа хранится в минутах.
  int EPrHT = EEPROM.read(FirstHeaterWarmupEepromAddress);
  if (EPrHT >= 1 && EPrHT <= 15) {
    FirstHeaterWarmupTime = (unsigned long)EPrHT * 60000UL;
  }

  int EPrF2 = EEPROM.read(FanSecondPWMEepromAddress);
  if (EPrF2 >= MinimumFanSecondPWM && EPrF2 <= MaximumFanSecondPWM) FanSecondPWM = EPrF2;

  int EPrFD = EEPROM.read(FanSecondDelayEepromAddress);
  if (EPrFD >= 0 && EPrFD <= 600) FanSecondSpeedDelay = (unsigned long)EPrFD * 1000UL;

  int EPrFE = EEPROM.read(FirstHeaterEnabledEepromAddress);
  if (EPrFE == 1) FirstHeaterEnabled = 1;
  else if (EPrFE == 2) FirstHeaterEnabled = 0;

  /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

  // Инициализируем DS18B20 один раз.
  // Дальше GetTemperature() использует эти объекты без повторного begin().
  WaterSensors.begin();
  FuelSensors.begin();
  WaterSensors.setWaitForConversion(true);
  FuelSensors.setWaitForConversion(true);
  WaterTemperatureValid = 0;
  FuelTemperatureValid = 0;
  WaterTemperatureErrorStartTime = 0;
  FuelTemperatureErrorStartTime = 0;

  //устанавливаем значение светимости
  //считывание фотодатчика
  FireSensorValue = ReadOpticalSensor(OpticalSensor);
  AmbientLumen = (FireSensorValue + LumenDiff);
}

//инвертируем датчик света (работает от 1250 до нуля где 1250 это темно а 0 это сильный свет.)
//делаем наоборот - 0 минимум, 1250 - максимум.
int ReadOpticalSensor(int SensorPort) {
  int Value = (1024 - analogRead(SensorPort));
  if (Value < 0) {
    Value = 0;
  } else if (Value > 1024) {
    Value = 1250;
  }
  return Value;
}


void UpdateFanSecondSpeed() {
  if (EmergencyExitCode == 1 || PowerLost != 0) {
    FanSecondSpeedActive = 0;
    FanSecondSpeedStartTime = 0;
    return;
  }
  if (FireShouldBeRunning == 1 && IgnitionShouldBeRunning == 0 && BurnerSuccessfullyIgnited == 1) {
    if (FanSecondSpeedStartTime == 0) FanSecondSpeedStartTime = millis();
    if (FanSecondSpeedActive == 0 && (unsigned long)(millis() - FanSecondSpeedStartTime) >= FanSecondSpeedDelay) {
      analogWrite(FanSwitch, FanSecondPWM);
      FanSecondSpeedActive = 1;
    }
  }
}

void UpdateCurrentData() {
  wdt_reset(); //сбрасываем вочдог


  if (EmergencyExitCode != 1 ) {
    UpdateFanSecondSpeed();
    //считывание фотодатчика
    FireSensorValue = ReadOpticalSensor(OpticalSensor);

    //считываем поплавок
    FuelLevelValue = digitalRead(FuelLevelSensor); // LOW = мало масла, HIGH = масла достаточно;

    // считывание датчиков температур
    WaterTemperatureSensorValue = GetTemperature(OneWireWaterTempSensorAddress);
    FuelTemperatureSensorValue = GetTemperature(OneWireFuelTempSensorAddress);

    // При недостоверной температуре не разрешаем ТЭН и насос.
    // Последнее значение остаётся на LCD, но управление по нему запрещено.
    if (!WaterTemperatureValid || !FuelTemperatureValid) {
      digitalWrite(HeaterSwitch, LOW);
      HeaterIsRunning = 0;
      digitalWrite(FuelPumpSwitch, LOW);
      PumpIsRunning = 0;
      analogWrite(IgnitionSwitch, 0);
      IgnitionShouldBeRunning = 0;
    }

    //проверяем нажата ли кнопка энкодера
    DebouncedEncoder.update();

    if ( DebouncedEncoder.read() == LOW ) {
      unsigned long PushTime = millis();
      while ( millis() < PushTime + SetupPushWaitTime && EmergencyExitCode != 1 ) {
        wdt_reset(); //сбрасываем вочдог
        DebouncedEncoder.update();
        if (DebouncedEncoder.read() == HIGH) {
          goto press_cancelled;
        }
      }
      DebouncedEncoder.update();
      if ( DebouncedEncoder.read() == LOW && InteractiveMode != 1 && EmergencyExitCode != 1 ) {
        InteractiveMode = 1;
      }

      if ( InteractiveMode == 1) {
        InteractiveMode = 0;
        SelectMenu();
      }
    }
press_cancelled:;

    //есть ли питание на 8 пине (5v от сети 220v) если нет то остановить горелку и отправить смс
    if (digitalRead(PowerInput) == LOW) {
      if (PowerLost == 0) {
        PowerLost = 1;
PrintMessage("PAUSE: NO 220v");
      }
      //стоп машина - питания нету
      NormalStop();
      goto finish;
    } else {
      if (PowerLost == 1) {
        PowerLost = 0;
}
    }

    // Контролируем погасание только после успешного розжига.
    // Во время процедуры розжига отсутствие пламени является нормальным.
    if (FireShouldBeRunning == 1 && IgnitionShouldBeRunning == 0) {
      if (FireSensorValue < AmbientLumen) {
        NormalStop();
      }
    }


    //проверяем температуру воды только по достоверному измерению
    if (WaterTemperatureValid && WaterTemperatureSensorValue >= CriticalWaterTemp) {
      EmergencyExitCode = 1;
      EmergencyStop("STOP: WATER TEMP");
      goto finish;
    }

    //проверяем температуру масла только по достоверному измерению
    if (FuelTemperatureValid && FuelTemperatureSensorValue >= CriticalFuelTemp) {
      //Serial.println(FuelTemperatureSensorValue);
      EmergencyExitCode = 1;
      EmergencyStop("STOP: OIL TEMP");
      goto finish;
    }

    lcd.setCursor(0, 0);
    Clean7();
    lcd.setCursor(0, 0);
    lcd.print("W:");
    lcd.setCursor(3, 0);
    lcd.print(WaterTemperatureSensorValue);

    lcd.setCursor(7, 0);
    Clean9();
    lcd.setCursor(7, 0);
    lcd.print("O:");
    lcd.setCursor(10, 0);
    lcd.print(FuelTemperatureSensorValue);

    if ( FuelLevelValue == HIGH ) {
      lcd.setCursor(0, 1);
      Clean7();
      lcd.setCursor(0, 1);
      lcd.print("L: OK ");
    }
    else {
      lcd.setCursor(0, 1);
      Clean7();
      lcd.setCursor(0, 1);
      lcd.print("L: LOW ");
    }
  }
finish:;
}


