void EmergencyStop(const char* SystemMessage) {
  //экстренная остановка горелки, выключаем все агрегаты
  //кроме экрана на котором выводим причину отключения
  //
  //Serial.println("EMERGENCY STOP");
  //Serial.println(SystemMessage);
  wdt_disable(); //отклчаем ребут по вочдогу
  digitalWrite (FanSwitch, LOW);
  digitalWrite (AirValve, LOW);
  digitalWrite (HeaterSwitch, LOW);
  digitalWrite (FuelPumpSwitch, LOW);
  analogWrite(IgnitionSwitch, 0);
  FanSecondSpeedActive = 0;
  FanSecondSpeedStartTime = 0;
  BurnerSuccessfullyIgnited = 0;
  EmergencyExitCode = 1;
//PrintMessage(SystemMessage);
}

int GetTemperature(int SensorPort) {
  if (EmergencyExitCode == 1) {
    return 0;
  }

  DallasTemperature *sensors = 0;
  boolean *temperatureValid = 0;
  unsigned long *errorStartTime = 0;
  const char *errorMessage = "STOP: SENSOR";

  if (SensorPort == OneWireWaterTempSensorAddress) {
    sensors = &WaterSensors;
    temperatureValid = &WaterTemperatureValid;
    errorStartTime = &WaterTemperatureErrorStartTime;
    errorMessage = "STOP: WATER SENSOR";
  }
  else if (SensorPort == OneWireFuelTempSensorAddress) {
    sensors = &FuelSensors;
    temperatureValid = &FuelTemperatureValid;
    errorStartTime = &FuelTemperatureErrorStartTime;
    errorMessage = "STOP: OIL SENSOR";
  }
  else {
    return 0;
  }

  DeviceAddress TempSensBus;
  boolean sensorFound = sensors->getAddress(TempSensBus, 0);
  if (!sensorFound) {
    *temperatureValid = 0;
    if (*errorStartTime == 0) *errorStartTime = millis();

    // Последнее корректное значение оставляем на LCD, но оно недостоверно
    // для управления. Через заданное время без восстановления — авария.
    if ((unsigned long)(millis() - *errorStartTime) >= TempSensErrorWaitTime) {
      EmergencyExitCode = 1;
      EmergencyStop(errorMessage);
    }

    if (SensorPort == OneWireWaterTempSensorAddress) return WaterTemperatureSensorValue;
    return FuelTemperatureSensorValue;
  }

  sensors->requestTemperatures();
  float temperature = sensors->getTempCByIndex(0);

  if (temperature == DEVICE_DISCONNECTED_C ||
      temperature < -55.0 ||
      temperature > 125.0) {

    *temperatureValid = 0;
    if (*errorStartTime == 0) *errorStartTime = millis();

    if ((unsigned long)(millis() - *errorStartTime) >= TempSensErrorWaitTime) {
      EmergencyExitCode = 1;
      EmergencyStop(errorMessage);
    }

    if (SensorPort == OneWireWaterTempSensorAddress) return WaterTemperatureSensorValue;
    return FuelTemperatureSensorValue;
  }

  // Корректное измерение: возвращаем датчик в рабочее состояние.
  *temperatureValid = 1;
  *errorStartTime = 0;

  int result = (int)temperature;

  if (SensorPort == OneWireWaterTempSensorAddress) {
    WaterTemperatureSensorValue = result;
  }
  else {
    FuelTemperatureSensorValue = result;
  }

  return result;
}

void Pause() {
  //Serial.println("Pause");
  //остановка горелки на паузу (вода нагрелась), выключаем агрегаты отвечающие за огонь
  FireShouldBeRunning = 0;
  FanSecondSpeedActive = 0;
  FanSecondSpeedStartTime = 0;
  BurnerSuccessfullyIgnited = 0;

  if (digitalRead(AirValve) == HIGH) {
    digitalWrite (AirValve, LOW);

  }
  analogWrite(IgnitionSwitch, 0);

  if (digitalRead(FanSwitch) == HIGH) {
    //digitalWrite (FanSwitch, LOW);
    //    продувка камеры сгорания свежим воздухом по завершению работы
    unsigned long StartFinalProduvkaTime = millis();
    while ( millis() < StartFinalProduvkaTime + FanShutDownTime && EmergencyExitCode != 1 ) {
      UpdateCurrentData();
    }
    digitalWrite (FanSwitch, LOW);
  }

  // PrintMessage(id);
  // delay(500);
