void PumpTheFuel() {
  /*
    МАСЛОНАСОС

    Полярность датчика сохранена как в исходном скетче:
      LOW  = низкий уровень масла -> насос ON
      HIGH = достаточный уровень -> насос OFF

    Первый запуск/запуск после выключения:
      - если масло < 50°C, уровень НЕ контролируется;
      - ТЭН включается сразу;
      - в течение FirstHeaterWarmupTime температура должна хотя бы
        немного вырасти;
      - если роста нет -> STOP: TEN FIRST;
      - после достижения 50°C первый прогрев заканчивается;
      - начиная с этого же вызова функции сразу проверяется уровень.

    Если масло при включении уже >= 50°C:
      - первый прогрев пропускается;
      - контроль уровня начинается сразу.

    Обычный режим:
      - LOW -> насос работает до восстановления уровня;
      - LOW + горелка горит -> ТЭН НЕ выключается из-за LOW;
      - LOW + горелка погашена -> ТЭН выключается;
      - HIGH -> насос выключается;
      - PumpTimeout -> STOP: NO FUEL.
  */

  // Авария или отсутствие сети: насос всегда выключен.
  if (EmergencyExitCode == 1 || PowerLost != 0) {
    digitalWrite(FuelPumpSwitch, LOW);
    PumpIsRunning = 0;
    return;
  }

  // Без достоверной температуры масла нельзя включать ТЭН или насос.
  if (!FuelTemperatureValid) {
    digitalWrite(FuelPumpSwitch, LOW);
    PumpIsRunning = 0;
    digitalWrite(HeaterSwitch, LOW);
    HeaterIsRunning = 0;
    return;
  }

  // ----------------------------------------------------------
  // ПЕРВЫЙ ПРОГРЕВ ТЭНА
  // ----------------------------------------------------------

  if (FirstHeaterStart == 1 && FirstHeaterEnabled == 1) {

    // Если масло уже >= 50°C, первый прогрев не нужен.
    if (FuelTemperatureSensorValue >= 50) {
      FirstHeaterStart = 0;
      FirstHeaterCheckActive = 0;
      FirstHeaterHeatingConfirmed = 0;
      FirstHeaterStartTime = 0;

      HeaterIsRunning = 0;
      digitalWrite(HeaterSwitch, LOW);
    }
    else {
      // Первый вход в процедуру.
      if (FirstHeaterCheckActive == 0) {
        FirstHeaterCheckActive = 1;
        FirstHeaterHeatingConfirmed = 0;
        FirstHeaterStartTime = millis();
        FirstHeaterInitialTemperature = FuelTemperatureSensorValue;

        HeaterIsRunning = 1;
        digitalWrite(HeaterSwitch, HIGH);

        lcd.setCursor(7, 1);
        Clean9();
        lcd.setCursor(7, 1);
        lcd.print("O: FIRST HEAT");
      }

      // Пока не достигли 50°C, датчик уровня НЕ проверяем.
      if (FuelTemperatureSensorValue > FirstHeaterInitialTemperature) {
        FirstHeaterHeatingConfirmed = 1;
      }

      // Если температура вообще не начала расти за заданное время,
      // считаем ТЭН неисправным.
      if (FirstHeaterHeatingConfirmed == 0 &&
          (unsigned long)(millis() - FirstHeaterStartTime) >= FirstHeaterWarmupTime) {

        HeaterIsRunning = 0;
        digitalWrite(HeaterSwitch, LOW);

        EmergencyExitCode = 1;
        EmergencyStop("STOP: TEN FIRST");
        return;
      }

      // Пока первый прогрев не завершён, насос не работает.
      digitalWrite(FuelPumpSwitch, LOW);
      PumpIsRunning = 0;
      return;
    }
  }

  // ----------------------------------------------------------
  // ОБЫЧНЫЙ КОНТРОЛЬ УРОВНЯ
  // ----------------------------------------------------------

  // LOW = мало масла.
  if (FuelLevelValue == LOW) {

    // Только при фактическом переходе насоса из OFF в ON
    // запускаем новый отсчёт PumpTimeout.
    if (PumpIsRunning == 0) {
      PumpStartTime = millis();
      PumpIsRunning = 1;
    }

    // Таймаут считается от момента запуска насоса.
    if ((unsigned long)(millis() - PumpStartTime) < PumpTimeout) {

      digitalWrite(FuelPumpSwitch, HIGH);

      // LOW больше не запрещает ТЭН, если горелка уже горит.
      // Если горелка погашена, при LOW ТЭН обязательно выключаем.
      // Исключение FirstHeaterStart уже обработано выше.
      if (FireShouldBeRunning == 0) {
        HeaterIsRunning = 0;
        digitalWrite(HeaterSwitch, LOW);

        lcd.setCursor(7, 1);
        Clean9();
        lcd.setCursor(7, 1);
        lcd.print("O: PAUSE");
      }

    }
    else {
      // За PumpTimeout уровень не восстановился.
      digitalWrite(FuelPumpSwitch, LOW);
      PumpIsRunning = 0;

      HeaterIsRunning = 0;
      digitalWrite(HeaterSwitch, LOW);

      EmergencyExitCode = 1;
      EmergencyStop("STOP: NO FUEL");
      return;
    }

  }
  else {
    // HIGH = масла достаточно.
    digitalWrite(FuelPumpSwitch, LOW);
    PumpIsRunning = 0;
  }
}

void HeatTheFuel() {
  if (EmergencyExitCode != 1) {
    if (!FuelTemperatureValid) {
      digitalWrite(HeaterSwitch, LOW);
      HeaterIsRunning = 0;
      HeaterWatchdogCounter = 0;
      return;
    }
    if (PowerLost == 0) {

      // Первый прогрев полностью выполняется в PumpTheFuel().
      if (FirstHeaterStart == 1 && FirstHeaterEnabled == 1) {
        return;
      }

      // LOW + горелка погашена: ТЭН запрещён.
      // LOW + горелка горит: ТЭН может работать по температуре.
      // HIGH: ТЭН работает по обычной температурной логике.
      if (FuelLevelValue == LOW && FireShouldBeRunning == 0) {
        HeaterIsRunning = 0;
        HeaterWatchdogCounter = 0;

        lcd.setCursor(7, 1);
        Clean9();
        lcd.setCursor(7, 1);
        lcd.print("O: PAUSE");

        digitalWrite(HeaterSwitch, LOW);
        return;
      }

      // Обычный режим: нагреваем масло по температуре.
      // Работа насоса сама по себе больше не блокирует ТЭН.
      {

        if (FuelTemperatureSensorValue < DesiredFuelTemp) {

          if (FuelTemperatureSensorValue < (DesiredFuelTemp - DesiredFuelGisteresisTemp)) {

            HeaterIsRunning = 1;

            // Старый контроль ТЭНа оставляем для обычного режима.
            if (FuelTemperatureSensorValue < 50) {

              if (HeaterWatchdogCounter == 0) {
                HeaterWatchdogTemp = FuelTemperatureSensorValue;
                HeaterWatchdogCounter++;

              } else if (HeaterWatchdogCounter < HeaterWatchdogMax) {
                HeaterWatchdogCounter++;

              } else if (HeaterWatchdogCounter >= HeaterWatchdogMax) {

                if (FuelTemperatureSensorValue > (HeaterWatchdogTemp + 1)) {
                  HeaterWatchdogCounter = 0;

                } else {
                  EmergencyExitCode = 1;
                  EmergencyStop("STOP: TEN");
                  return;
                }
              }

            } else {
              HeaterWatchdogCounter = 0;
            }

            lcd.setCursor(7, 1);
            Clean9();
            lcd.setCursor(7, 1);
            lcd.print("O: HEAT ");

            digitalWrite(HeaterSwitch, HIGH);

          }

        } else {

          HeaterIsRunning = 0;
          HeaterWatchdogCounter = 0;

          lcd.setCursor(7, 1);
          Clean9();
          lcd.setCursor(7, 1);
          lcd.print("O: PAUSE");

          digitalWrite(HeaterSwitch, LOW);
        }

      }
    }
  }
}


void Fire() {
  if (EmergencyExitCode != 1 ) {
    if (PowerLost == 0) {
      int IgnitionCounter = 0;
      // Новая попытка розжига всегда начинается без разрешения FAN2.
      BurnerSuccessfullyIgnited = 0;
      FanSecondSpeedActive = 0;
      FanSecondSpeedStartTime = 0;
      //зажигание стартует
      IgnitionShouldBeRunning = 1;
      while ( FireSensorValue <= AmbientLumen && PumpIsRunning != 1 && HeaterIsRunning != 1 && FuelLevelValue != LOW && IgnitionAttempts > IgnitionCounter && EmergencyExitCode != 1 && PowerLost == 0 ) {
        NormalStop();
        // запуск продувки камеры сгорание свежим воздухом
        unsigned long StartProduvkaTime = millis();
        analogWrite (FanSwitch, FanSwitchPWM);

        while ( millis() < StartProduvkaTime + FanStartUpTime && EmergencyExitCode != 1 && PowerLost == 0) {
          UpdateCurrentData();
        }

        // остановка продувки на паузу перед зажиганием пламени
        unsigned long StopProduvkaTime = millis();
        digitalWrite (FanSwitch, LOW);

        while ( millis() < StopProduvkaTime + FanPreIgnitionPauseTime && EmergencyExitCode != 1 && PowerLost == 0 ) {
          UpdateCurrentData();
        }


        unsigned long StartIgnitionTime = millis();
        //если огонь не горит - запустить искру и вентилятор с клапаном воздуха
        if ( FireSensorValue <= AmbientLumen ) {
          digitalWrite (AirValve, HIGH);
          //delay(PreIgnitionFanDelay);
          analogWrite(IgnitionSwitch, IgnitionImpulseFrequency);
          delay(PreIgnitionFanDelay);
          //digitalWrite (FanSwitch, HIGH);
          analogWrite (FanSwitch, FanSwitchPWM);
        }

        //пауза горелки
        while ( millis() < StartIgnitionTime + IgnitionTime && EmergencyExitCode != 1 && PowerLost == 0) {
          UpdateCurrentData();
        }
        //если огонь не загорелся - выключить клапана и искру
        if ( FireSensorValue < AmbientLumen ) {
          Pause();
        } else {
          // Пламя обнаружено: искра больше не нужна.
          analogWrite(IgnitionSwitch, 0);

          // Розжиг завершён: искра сразу выключается.
          IgnitionShouldBeRunning = 0;
          FireShouldBeRunning = 1;
          BurnerSuccessfullyIgnited = 1;
          FanSecondSpeedActive = 0;
          FanSecondSpeedStartTime = millis();
          analogWrite(FanSwitch, FanSwitchPWM);
        }
        UpdateCurrentData();
        IgnitionCounter++;
        if (IgnitionAttempts == IgnitionCounter && FireSensorValue <= AmbientLumen  && PowerLost == 0) {
          EmergencyExitCode = 1;
          EmergencyStop("STOP: IGNITION");
          goto finish;
        }
      }
    }
  }
finish:;
  // Процедура розжига в любом случае завершена.
  // Искра не должна оставаться включенной после выхода из Fire().
  analogWrite(IgnitionSwitch, 0);
  IgnitionShouldBeRunning = 0;
}


void SelectMenu() {
  wdt_disable(); //отклчаем ребут по вочдогу
  NormalStop();
  PrintMessage("      MENU     ");
  delay(1000);//wait encoder button to calm down)
  lcd.clear();

  int SelectedValue = 0;
  //инициализируем поворотную кнопку (энкодер)
  Rotary r = Rotary(EncoderBack, EncoderForward);
  boolean EncoderTurned = 0;
  PrintDualMessage("      MENU      ", "   <<- | ->>   " );
  while (digitalRead(EncoderButton) != LOW && EmergencyExitCode != 1) {
    unsigned char RotaryDirection = r.process();
    if (RotaryDirection) {

      EncoderTurned = 1;

      if (RotaryDirection == DIR_CCW) {
        SelectedValue--;
      }
      else {
        SelectedValue++;
      }

      if (SelectedValue < 0) {
        SelectedValue = 3;
      }

      if (SelectedValue > 3) {
        SelectedValue = 0;
      }


      if ((SelectedValue == 1) and (OperationMode == 1)) {
        PrintMessage("  BURN OFF?");
      }
      else if ((SelectedValue == 1) and (OperationMode == 0)) {
        PrintMessage("  BURN ON?");
      }
      else if (SelectedValue == 0) {
        PrintMessage("  SETUP?");
      }
      else if (SelectedValue == 2) {
        PrintMessage("  RESET?");
      }
      else if (SelectedValue == 3) {
        PrintMessage("  EXIT?");
      }

    }
  }
  if (( EmergencyExitCode != 1 ) and ( EncoderTurned == 1 )) {
    if ((SelectedValue == 1) and (OperationMode == 1)) {
      EEPROM.update(OperationEepromAddress, 0);
      PrintMessage("OK");
      delay(2000);
      lcd.clear();
      SoftReset();
    }
    else if ((SelectedValue == 1) and (OperationMode == 0)) {
      EEPROM.update(OperationEepromAddress, 1);
      PrintMessage("OK");
      delay(2000);
      lcd.clear();
      SoftReset();
    }
    else if (SelectedValue == 0) {
      PrintMessage("OK");
      delay(2000);
      lcd.clear();
      InteractiveInput();
    }
    else if (SelectedValue == 2) {
      PrintMessage("OK");
      Reset();
      delay(2000);
      lcd.clear();
      SoftReset();
    }
    else if (SelectedValue == 3) {
      PrintMessage("OK");
      delay(2000);
      lcd.clear();
      SoftReset();
    }
  }
  else {
    PrintMessage("OK");
    delay(2000);
    lcd.clear();
    SoftReset();
  }
}


